import { gunzipSync } from "fflate";
import { EmojiType } from "./EmojiPicker";

export const emojiGzipBase64 = ``;

let cachedJson: { emojis: EmojiType[] } | null = null;

export function loadEmojiJson() {
  if (cachedJson) return cachedJson;

  const binary = Uint8Array.from(atob(emojiGzipBase64), c => c.charCodeAt(0));

  const decompressed = gunzipSync(binary);

  const jsonStr = new TextDecoder().decode(decompressed);
  cachedJson = JSON.parse(jsonStr) as { emojis: EmojiType[] };

  return cachedJson;
}
